const ruler = (r, testsBranch) => agent(RULES + '\nRole: ruler (Engineer), rules.md section (e). Builder branch origin/' + r.branch + ' stopped with: ' + r.stop_reason + '\nSpec: ' + SPEC + '.' + IFACE_NOTE + ' Rulebook: docs/northstar/plans/2026-10-07-visible-game-rulebook.md (its "Decision procedure" word for word). Ledger ' + LEDGER + ': a test-defect gets the new row TD-HARNESS-KEEPRED. Branch push/vg-keepred-rulings (suffix vg-keepred-rulings; continue it from origin if it exists, else cut it from origin/' + testsBranch + ' so your edit is a delta on the writer\'s file). If every condition of the procedure holds: edit only the one test file named, run it alone and its positive control, append the ledger row, push, report ruled true with row and branch. Else report ruled false and brief (under one page: test id and failing line, the builder\'s claim, the spec and bible lines that bear on it, two or three options with what each changes). A threshold, a window, a tolerance or a Westley-owned number is never ruled: ruled false. A test-defect that would change an interface item T1 to T9 of the ruling above is ruled false.', { label: 'rule:' + r.branch, phase: 'Build', schema: RULING, agentType: 'engineer', model: 'sonnet' })
